def classify(rows):
    statuses = {str(st).strip().lower() if st is not None else '' for _, st, _ in rows}
    has_ns = any('no show' in s for s in statuses)
    has_sch = any(s == 'sch' for s in statuses)
    if has_ns and has_sch:
        return 'NS/SCHED'
    if has_sch and not has_ns:
        return 'FUTURE'
    # only No Show
    if has_ns:
        # check E for no-show rows: any date present -> NO ACTION NEEDED, else CALL PT
        any_date = False
        all_empty = True
        for _, st, e_val in rows:
